/* ============================================================================
 * NODE 1/5 — Build fetch plan
 * n8n Code node · Language: JavaScript · Mode: Run Once for All Items
 * ----------------------------------------------------------------------------
 * Emits one item per (symbol, interval). The HTTP Request node downstream runs
 * once per item automatically, so N series cost N calls but still ONE n8n
 * execution. That is the whole reason this is a fan-out array and not a set of
 * sub-workflows.
 *
 * >>> EXTENSION SEAM <<<
 * To add an asset, add an entry to ASSETS. Nothing else in the workflow
 * changes. Check the budget first:
 *
 *   calls/day = (3 x assets + 1) x runs/day    (~48 runs/day)
 *
 *   1 asset  ->  192/day   24% of Twelve Data free tier (800/day)
 *   2 assets ->  336/day   42%
 *   3 assets ->  480/day   60%
 *   5 assets ->  768/day   96%  <- ceiling
 *   6 assets ->  912/day   exceeds free tier, needs a paid plan
 *
 * n8n executions do NOT change with asset count. The data API is the
 * binding constraint.
 * ==========================================================================*/

/* >>> LANGUAGE <<<
 * One setting, read by the Scorer (setup notes), Format message (all labels and
 * the disclaimer) and the LLM prompt (which language to write prose in).
 * Supported: 'ru', 'en'. Change it here only — nothing else needs editing.
 *
 * Prices stay in 1,234.56 format in every language. Trading channels use that
 * convention regardless of locale, and it keeps the LLM's decimal separator
 * consistent with the signal block (see the note in 05-format.js about why a
 * Russian-style comma decimal would trip the number validator).
 */
const LANG = 'ru';

const ASSETS = [
  {
    symbol: 'XAU/USD',
    label: { ru: 'ЗОЛОТО', en: 'GOLD' },
    emoji: '\u{1F7E1}', // yellow circle
    series: [
      { interval: '15min', outputsize: 100 }, // entry timing, compression
      { interval: '1h', outputsize: 200 },    // EMA 200 needs 200 bars
      { interval: '1day', outputsize: 60 },   // prior-day levels, daily ATR
    ],
  },
];

// Shared context series. Fetched once and reused by every asset, so adding a
// second asset costs 3 calls, not 4.
const CONTEXT = [
  {
    symbol: 'EUR/USD',
    interval: '1h',
    outputsize: 20,
    role: 'dollar_proxy',
  },
];

const plan = [];

for (const asset of ASSETS) {
  for (const s of asset.series) {
    plan.push({
      json: {
        role: 'asset',
        symbol: asset.symbol,
        interval: s.interval,
        outputsize: s.outputsize + 1, // room for the API's current forming bar
        closedBars: s.outputsize,
        // Resolve the display name for the active language, falling back to the
        // raw value so a plain string still works if someone edits ASSETS.
        label:
          typeof asset.label === 'string'
            ? asset.label
            : asset.label[LANG] || asset.label.en,
        emoji: asset.emoji,
        lang: LANG,
      },
      // 1:N fan-out — without pairedItem, downstream nodes that expect item
      // lineage fail with paired_item_no_info.
      pairedItem: { item: 0 },
    });
  }
}

for (const c of CONTEXT) {
  plan.push({
    json: {
      role: c.role,
      symbol: c.symbol,
      interval: c.interval,
      outputsize: c.outputsize + 1,
      closedBars: c.outputsize,
      label: null,
      emoji: null,
      lang: LANG,
    },
    pairedItem: { item: 0 },
  });
}

// Fail loudly rather than posting a message built from nothing.
if (plan.length === 0) {
  throw new Error('Fetch plan is empty — check the ASSETS config array.');
}

return plan;

/* ============================================================================
 * NODE 2/5 — Indicators
 * n8n Code node · Language: JavaScript · Mode: Run Once for All Items
 * ----------------------------------------------------------------------------
 * Turns raw Twelve Data responses into the indicator set the scorer consumes.
 * Nothing here makes a decision; it only measures.
 *
 * TWELVE DATA RESPONSE NOTES (these bite if forgotten):
 *   - `values` is NEWEST-FIRST. Everything below reverses to oldest-first
 *     immediately and works chronologically thereafter.
 *   - Every OHLC field is a STRING. parseFloat everywhere.
 *   - No `volume` for metals/forex. Do not depend on it.
 *   - Errors come back HTTP 200 with {status:"error", code, message}.
 *   - Responses are matched to the fetch plan by meta.symbol + meta.interval,
 *     not by item order. Order is not contractual.
 *
 * CLOSED BARS: use open + interval <= now, including full UTC daily bars.
 * STALENESS GATE: require fresh 15m, hourly and FX bars. Daily history allows
 * weekends and one missing weekday for a market holiday. We return [] when
 * coverage is stale, ending the run with no post.
 * ==========================================================================*/

const DAY_MS = 86400000;
const INTERVAL_MS = { '15min': 900000, '1h': 3600000, '1day': DAY_MS };
const MAX_BAR_AGE_MIN = { '15min': 60, '1h': 180 };

// ---------------------------------------------------------------- helpers ---

/** Wilder EMA. Seeds from the SMA of the first `period` values. */
function ema(values, period) {
  if (!Array.isArray(values) || values.length < period) return null;
  const k = 2 / (period + 1);
  let acc = 0;
  for (let i = 0; i < period; i++) acc += values[i];
  let e = acc / period;
  for (let i = period; i < values.length; i++) {
    e = values[i] * k + e * (1 - k);
  }
  return e;
}

/** Wilder ATR. bars are oldest-first {high, low, close}. */
function atr(bars, period) {
  if (!Array.isArray(bars) || bars.length < period + 1) return null;
  const tr = [];
  for (let i = 1; i < bars.length; i++) {
    const prevClose = bars[i - 1].close;
    tr.push(
      Math.max(
        bars[i].high - bars[i].low,
        Math.abs(bars[i].high - prevClose),
        Math.abs(bars[i].low - prevClose),
      ),
    );
  }
  let acc = 0;
  for (let i = 0; i < period; i++) acc += tr[i];
  let a = acc / period;
  for (let i = period; i < tr.length; i++) {
    a = (a * (period - 1) + tr[i]) / period;
  }
  return a;
}

function highest(bars, n, key) {
  const slice = bars.slice(-n);
  return slice.reduce((m, b) => (b[key] > m ? b[key] : m), -Infinity);
}

function lowest(bars, n, key) {
  const slice = bars.slice(-n);
  return slice.reduce((m, b) => (b[key] < m ? b[key] : m), Infinity);
}

function round(n, dp) {
  if (n === null || n === undefined || !Number.isFinite(n)) return null;
  const f = Math.pow(10, dp);
  return Math.round(n * f) / f;
}

/**
 * Twelve Data intraday datetime is "YYYY-MM-DD HH:mm:ss" with no zone marker.
 * We request timezone=UTC on the HTTP node, so append Z to parse it as UTC
 * rather than letting the runtime guess local time.
 */
function parseBarTime(dt) {
  if (!dt) return null;
  const iso = dt.length <= 10 ? `${dt}T00:00:00Z` : `${dt.replace(' ', 'T')}Z`;
  const ms = Date.parse(iso);
  return Number.isFinite(ms) ? ms : null;
}

/** Normalise one Twelve Data response into oldest-first numeric bars. */
function toBars(body) {
  return body.values
    .map((v) => ({
      t: parseBarTime(v.datetime),
      datetime: v.datetime,
      open: parseFloat(v.open),
      high: parseFloat(v.high),
      low: parseFloat(v.low),
      close: parseFloat(v.close),
    }))
    .filter(
      (b) =>
        b.t !== null &&
        Number.isFinite(b.open) &&
        Number.isFinite(b.high) &&
        Number.isFinite(b.low) &&
        Number.isFinite(b.close),
    )
    .sort((a, b) => a.t - b.t); // oldest-first, explicitly — do not trust order
}

function sessionForHour(h) {
  if (h < 7) return 'asia';
  if (h < 13) return 'london';
  if (h < 17) return 'ny_overlap';
  if (h < 21) return 'ny_afternoon';
  return 'late';
}

// --------------------------------------------------- collect the responses ---

const responses = $input.all();
const plan = $('Build fetch plan').all().map((i) => i.json);
const nowMs = Date.now();

// Keyed "SYMBOL|interval" -> bars
const series = {};

for (const item of responses) {
  const body = item.json || {};

  if (body.status !== 'ok' || !Array.isArray(body.values)) {
    // Surfaces as a workflow error -> error workflow DMs the owner.
    // Common causes: exhausted API credits (429), bad symbol, expired key.
    const detail = body.message || JSON.stringify(body).slice(0, 300);
    throw new Error(`Twelve Data request failed: ${detail}`);
  }

  const sym = body.meta && body.meta.symbol;
  const ivl = body.meta && body.meta.interval;
  if (!sym || !ivl) {
    throw new Error('Twelve Data response missing meta.symbol / meta.interval');
  }

  const bars = toBars(body);
  if (bars.length === 0) {
    throw new Error(`Twelve Data returned no usable bars for ${sym} ${ivl}`);
  }
  const cfg = plan.find((p) => p.symbol === sym && p.interval === ivl);
  if (!INTERVAL_MS[ivl]) throw new Error(`Unsupported candle interval: ${ivl}`);
  series[`${sym}|${ivl}`] = bars
    .filter((b) => b.t + INTERVAL_MS[ivl] <= nowMs)
    .slice(-(cfg?.closedBars || cfg?.outputsize || bars.length));
}

// Display metadata lives in the fetch plan so config stays in exactly one node.
const assetCfg = plan.find((p) => p.role === 'asset');
if (!assetCfg) throw new Error('No asset row found in the fetch plan.');

const SYM = assetCfg.symbol;
const m15 = series[`${SYM}|15min`];
const h1 = series[`${SYM}|1h`];
const d1 = series[`${SYM}|1day`];

const dollarCfg = plan.find((p) => p.role === 'dollar_proxy');
const fx = dollarCfg ? series[`${dollarCfg.symbol}|${dollarCfg.interval}`] : null;

for (const [name, arr] of [['15min', m15], ['1h', h1], ['1day', d1]]) {
  if (!arr) throw new Error(`Missing ${SYM} ${name} series in responses.`);
}
if (dollarCfg && !fx) throw new Error(`Missing ${dollarCfg.symbol} ${dollarCfg.interval} series in responses.`);

// -------------------------------------------------------- staleness gate ----

for (const cfg of plan) {
  const bars = series[`${cfg.symbol}|${cfg.interval}`];
  if (!bars) throw new Error(`Missing ${cfg.symbol} ${cfg.interval} series in responses.`);
  const newest = bars[bars.length - 1];
  let stale = !newest;
  if (newest && cfg.interval === '1day') {
    // ponytail: one missing weekday permits holidays; an exchange calendar is
    // needed only if multi-day weekday closures must remain tradable.
    const today = Math.floor(nowMs / DAY_MS) * DAY_MS;
    let missingWeekdays = 0;
    for (let day = newest.t + DAY_MS; day < today; day += DAY_MS) {
      const weekday = new Date(day).getUTCDay();
      if (weekday !== 0 && weekday !== 6 && ++missingWeekdays > 1) {
        stale = true;
        break;
      }
    }
  } else if (newest) {
    stale = (nowMs - newest.t) / 60000 > MAX_BAR_AGE_MIN[cfg.interval];
  }
  if (stale) {
    const sd = $getWorkflowStaticData('global');
    sd.skipped = (sd.skipped || 0) + 1;
    sd.lastSkipAt = new Date(nowMs).toISOString();
    console.log(`Market closed or data stale: ${cfg.symbol} ${cfg.interval} lacks fresh closed bars. Skipping run.`);
    return []; // ends the run, posts nothing
  }
}
const newest15 = m15[m15.length - 1];
const barAgeMin = (nowMs - newest15.t) / 60000;

// ------------------------------------------------------------ indicators ----

const price = newest15.close;
const closes1h = h1.map((b) => b.close);

const ema20 = ema(closes1h, 20);
const ema50 = ema(closes1h, 50);
const ema200 = ema(closes1h, 200); // null if fewer than 200 bars returned
const atr1h = atr(h1, 14);
const atrDaily = atr(d1, 14);

if (!Number.isFinite(atr1h) || atr1h <= 0) {
  throw new Error('ATR(1h) could not be computed — insufficient 1h history.');
}

// Every daily input is complete, so the newest bar is the prior trading day.
const priorDay = d1[d1.length - 1];

// EMA stack: +1 aligned up, -1 aligned down, 0 mixed/unknown.
let emaStack = 0;
if (ema20 !== null && ema50 !== null && ema200 !== null) {
  if (ema20 > ema50 && ema50 > ema200) emaStack = 1;
  else if (ema20 < ema50 && ema50 < ema200) emaStack = -1;
}

// Daily trend, independent of the 1h stack. Used for the conflict penalty.
const dailyCloses = d1.map((b) => b.close);
const dailyEma20 = ema(dailyCloses, 20);
let dailyTrend = 0;
if (dailyEma20 !== null) {
  if (price > dailyEma20 * 1.001) dailyTrend = 1;
  else if (price < dailyEma20 * 0.999) dailyTrend = -1;
}

// Compression: 8-bar 15m range relative to 1h ATR. < 0.6 is a squeeze.
// The bounds are exported too — range_squeeze publishes them as the levels to
// watch, since it has no directional bias of its own.
const range8High = highest(m15, 8, 'high');
const range8Low = lowest(m15, 8, 'low');
const range8 = range8High - range8Low;
const compressionRatio = range8 / atr1h;

// 24h change. 96 x 15m bars = 24h; fall back to prior-day close if short.
const idx24h = m15.length - 1 - 96;
const ref24h = idx24h >= 0 ? m15[idx24h].close : priorDay.close;
const change24hPct = ((price - ref24h) / ref24h) * 100;

// 1h swing structure over the last 20 bars.
const swingHigh = highest(h1, 20, 'high');
const swingLow = lowest(h1, 20, 'low');

// 5-day range position, 0 (at lows) .. 1 (at highs).
const hi5 = highest(d1, 5, 'high');
const lo5 = lowest(d1, 5, 'low');
const rangePos5d = hi5 > lo5 ? (price - lo5) / (hi5 - lo5) : 0.5;

// Dollar proxy. EUR/USD up means dollar down, which supports gold, so the
// sign of this slope maps directly onto a bullish-gold reading.
let dollarSlopePct = null;
let dollarDir = 0; // +1 supports gold longs, -1 supports shorts, 0 neutral
if (fx && fx.length >= 5) {
  const a = fx[fx.length - 5].close;
  const b = fx[fx.length - 1].close;
  dollarSlopePct = ((b - a) / a) * 100;
  if (dollarSlopePct > 0.05) dollarDir = 1;
  else if (dollarSlopePct < -0.05) dollarDir = -1;
}

// Session, and the range of the current session so far.
const nowUTC = new Date(nowMs);
const hourUTC = nowUTC.getUTCHours();
const session = sessionForHour(hourUTC);

const sessionStartHour = { asia: 0, london: 7, ny_overlap: 13, ny_afternoon: 17, late: 21 }[session];
const sessionStartMs = Date.UTC(
  nowUTC.getUTCFullYear(),
  nowUTC.getUTCMonth(),
  nowUTC.getUTCDate(),
  sessionStartHour,
);
const sessionBars = m15.filter((b) => b.t >= sessionStartMs);
const sessionHigh = sessionBars.length ? Math.max(...sessionBars.map((b) => b.high)) : null;
const sessionLow = sessionBars.length ? Math.min(...sessionBars.map((b) => b.low)) : null;

// First-hour range of the current session (4 x 15m bars from session open).
const firstHourBars = m15.filter(
  (b) => b.t >= sessionStartMs && b.t < sessionStartMs + 60 * 60 * 1000,
);
const firstHourHigh = firstHourBars.length >= 2 ? Math.max(...firstHourBars.map((b) => b.high)) : null;
const firstHourLow = firstHourBars.length >= 2 ? Math.min(...firstHourBars.map((b) => b.low)) : null;

// Last two closed 15m bars — used for break-and-hold confirmation.
const prev15 = m15.length >= 2 ? m15[m15.length - 2] : null;

return [
  {
    json: {
      // identity / display
      symbol: SYM,
      label: assetCfg.label,
      emoji: assetCfg.emoji,
      lang: assetCfg.lang || 'ru',
      tsUtc: new Date(nowMs).toISOString(),
      barAgeMin: round(barAgeMin, 1),

      // price
      price: round(price, 2),
      change24hPct: round(change24hPct, 2),

      // 1h trend
      ema20: round(ema20, 2),
      ema50: round(ema50, 2),
      ema200: round(ema200, 2),
      emaStack,
      dailyTrend,

      // volatility
      atr1h: round(atr1h, 2),
      atrDaily: round(atrDaily, 2),
      atrPctOfPrice: round((atr1h / price) * 100, 3),

      // structure
      priorDayHigh: round(priorDay.high, 2),
      priorDayLow: round(priorDay.low, 2),
      priorDayClose: round(priorDay.close, 2),
      priorDayDate: priorDay.datetime.slice(0, 10),
      swingHigh: round(swingHigh, 2),
      swingLow: round(swingLow, 2),
      rangePos5d: round(rangePos5d, 3),

      // compression
      range8: round(range8, 2),
      range8High: round(range8High, 2),
      range8Low: round(range8Low, 2),
      compressionRatio: round(compressionRatio, 3),

      // session
      session,
      hourUTC,
      sessionStartHour,
      sessionHigh: round(sessionHigh, 2),
      sessionLow: round(sessionLow, 2),
      firstHourHigh: round(firstHourHigh, 2),
      firstHourLow: round(firstHourLow, 2),

      // intermarket
      dollarSlopePct: round(dollarSlopePct, 3),
      dollarDir,

      // raw bars the scorer needs for break/sweep detection
      last15: {
        open: round(newest15.open, 2),
        high: round(newest15.high, 2),
        low: round(newest15.low, 2),
        close: round(newest15.close, 2),
        datetime: newest15.datetime,
      },
      prev15: prev15
        ? {
            open: round(prev15.open, 2),
            high: round(prev15.high, 2),
            low: round(prev15.low, 2),
            close: round(prev15.close, 2),
            datetime: prev15.datetime,
          }
        : null,
    },
    pairedItem: { item: 0 },
  },
];

/* ============================================================================
 * NODE 3/5 — Event gate
 * n8n Code node · Language: JavaScript · Mode: Run Once for All Items
 * ----------------------------------------------------------------------------
 * Answers one question: how close are we to a high-impact USD release?
 *
 * This is the highest-value single component in the workflow. Most retail
 * damage on gold happens in the fifteen minutes either side of a CPI, NFP or
 * FOMC print. A bot that knows to stand aside there is worth more than one
 * that knows an EMA crossed.
 *
 * WHY THE TRY/CATCH MATTERS: a Code node has no retryOnFail. An unhandled
 * throw here kills the whole run and the channel goes silent. So a calendar
 * outage degrades instead of failing:
 *     fresh cache  -> use it
 *     stale cache  -> use it for at most 24 hours, flag staleness
 *     expired/no cache -> eventDataUnknown = true, scorer applies a precautionary
 *                     penalty rather than assuming the coast is clear
 *
 * KNOWN LIMITATION: the feed covers the current FF week (Sunday–Saturday).
 * A Friday run cannot see the following Monday's events. Since the gate only
 * reacts inside a 120-minute window, that gap is harmless.
 * ==========================================================================*/

const CALENDAR_URL = 'https://nfs.faireconomy.media/ff_calendar_thisweek.json';
const CACHE_TTL_MIN = 360;   // 6 hours -> ~4 fetches/day
const MAX_CACHE_AGE_MIN = 24 * 60;
const POST_EVENT_WINDOW = 15; // minutes after a print where price is still noise

const ctx = $input.first().json;
const sd = $getWorkflowStaticData('global');
const nowMs = Date.now();

// ------------------------------------------------------ cache read / fetch ---

let events = Array.isArray(sd.calendarEvents) ? sd.calendarEvents : null;
const fetchedAt = sd.calendarFetchedAt ? Date.parse(sd.calendarFetchedAt) : 0;
const cacheAgeMin = Number.isFinite(fetchedAt) && fetchedAt > 0 && fetchedAt <= nowMs
  ? (nowMs - fetchedAt) / 60000 : Infinity;

let eventDataUnknown = false;
let calendarStale = false;
let calendarSource = 'cache';

if (!events || cacheAgeMin > CACHE_TTL_MIN) {
  try {
    // NOTE: this.helpers.httpRequest — NOT $helpers, which is undefined in the
    // n8n 2.x task-runner sandbox and throws ReferenceError.
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: CALENDAR_URL,
      json: true,
      timeout: 10000,
    });

    // The endpoint serves a bare JSON array, sometimes as text/plain.
    const parsed = typeof res === 'string' ? JSON.parse(res) : res;
    if (!Array.isArray(parsed)) throw new Error('Calendar payload was not an array');

    events = parsed
      .filter((e) => e && e.country === 'USD' && e.impact === 'High')
      .map((e) => ({
        title: String(e.title || 'Unnamed event'),
        // FF dates carry a US-Eastern offset, so Date.parse handles the zone.
        ts: Date.parse(e.date),
      }))
      .filter((e) => Number.isFinite(e.ts))
      .sort((a, b) => a.ts - b.ts);

    sd.calendarEvents = events;
    sd.calendarFetchedAt = new Date(nowMs).toISOString();
    calendarSource = 'fetched';
    console.log(`Calendar refreshed: ${events.length} high-impact USD events this week.`);
  } catch (err) {
    // Degrade, never die.
    if (Array.isArray(sd.calendarEvents) && cacheAgeMin <= MAX_CACHE_AGE_MIN) {
      events = sd.calendarEvents;
      calendarStale = true;
      calendarSource = 'stale_cache';
      console.log(`Calendar fetch failed (${err.message}); using cache from ${sd.calendarFetchedAt}.`);
    } else {
      events = [];
      eventDataUnknown = true;
      calendarStale = Array.isArray(sd.calendarEvents);
      calendarSource = 'unavailable';
      console.log(`Calendar fetch failed (${err.message}) and no usable cache exists; assuming event risk.`);
    }
  }
}

// -------------------------------------------------------------- proximity ---

let minutesToNext = null;
let nextEventTitle = null;
let nextEventTsUtc = null;

const upcoming = events.filter((e) => e.ts > nowMs);
if (upcoming.length > 0) {
  const next = upcoming[0];
  minutesToNext = Math.round((next.ts - nowMs) / 60000);
  nextEventTitle = next.title;
  nextEventTsUtc = new Date(next.ts).toISOString();
}

// Did something just print? Price is unreliable for a few minutes afterwards.
let minutesSinceLast = null;
let lastEventTitle = null;
const past = events.filter((e) => e.ts <= nowMs);
if (past.length > 0) {
  const last = past[past.length - 1];
  minutesSinceLast = Math.round((nowMs - last.ts) / 60000);
  lastEventTitle = last.title;
}
const inPostEventWindow =
  minutesSinceLast !== null && minutesSinceLast <= POST_EVENT_WINDOW;

/** Human-readable countdown for the message footer. */
function humanise(min) {
  if (min === null) return null;
  if (min < 60) return `${min} min`;
  if (min < 60 * 24) return `${Math.round(min / 60)}h`;
  return `${Math.round(min / (60 * 24))}d`;
}

return [
  {
    json: {
      ...ctx,
      eventGate: {
        minutesToNext,
        nextEventTitle,
        nextEventTsUtc,
        nextEventHuman: humanise(minutesToNext),
        minutesSinceLast,
        lastEventTitle,
        inPostEventWindow,
        eventDataUnknown,
        calendarStale,
        calendarSource,
        eventCount: events.length,
      },
    },
    pairedItem: { item: 0 },
  },
];

/* ============================================================================
 * NODE 4/5 — Scorer
 * n8n Code node · Language: JavaScript · Mode: Run Once for All Items
 * ----------------------------------------------------------------------------
 * Deterministic. Given the same indicators it always produces the same winner.
 * The LLM downstream never sees this logic and cannot alter a single number.
 *
 * >>> EXTENSION SEAM <<<
 * Add a signal by appending to GENERATORS. A generator returns null when its
 * pattern is absent, or a candidate object. Everything after that — scoring,
 * stops, targets, banding — is shared and needs no change.
 *
 * >>> CALIBRATION KNOB <<<
 * WEIGHTS below is a v1 hypothesis, not a validated model. Nobody can tell you
 * the right number for "dollar agrees" without data. The Google Sheets log
 * records which terms fired on every run; after ~2-3 weeks reweight against
 * observed outcomes. Treat these as a starting point.
 * ==========================================================================*/

const WEIGHTS = {
  emaAgrees: 15,
  dollarAgrees: 12,
  volatilityFits: 10,
  sessionFits: 8,
  goodRR: 10,
  eventWithin60: -40,
  eventWithin120: -20,
  dailyConflict: -12,
  breakoutInAsia: -10,
};

const BANDS = { high: 70, medium: 50, low: 30 };
// Above this score every confirmation has stacked and the setup is crowded; the
// backtest shows it reverses (see the CROWDING CEILING note in the banding
// section). Demoted to LOW rather than published as HIGH.
const CROWDED_CEILING = 90;

const STOP_FLOOR_PCT = 0.0030; // 0.30% — ~7 pts at 2,400
const STOP_CEIL_PCT = 0.0080;  // 0.80% — ~19 pts at 2,400
const STOP_BUFFER_ATR = 0.15;  // how far past the structural level the stop sits
const MIN_TARGET_R = 1.2;      // a level closer than this isn't worth targeting
const MAX_TARGET_R = 4.0;      // ...and one further than this is a SWING target
const DEFAULT_TARGET_R = 2.0;  // fallback when no level is in range

const c = $input.first().json;
const gate = c.eventGate || {};

/* ---------------------------------------------------------------- strings ---
 * Language comes from LANG in 01-fetch-plan.js — do not set it here.
 * These are the strings this node produces: generator display names, the setup
 * notes, and the language name handed to the LLM prompt.
 * Format message owns the message chrome and has its own table.
 */
const STRINGS = {
  ru: {
    langName: 'Russian (русский)',
    noSetup: 'Сетап не сформирован.',
    // ForexFactory event titles arrive in English. Unmapped titles fall through
    // unchanged — the acronyms (FOMC, CPI, NFP, PMI) are used untranslated by
    // Russian traders anyway, so an unknown event still reads sensibly.
    // Lives here rather than in Format because the LLM facts (built below) must
    // carry the localised name too, or the prose and the chrome disagree.
    eventNames: {
      'FOMC Meeting Minutes': 'протокол FOMC',
      'FOMC Statement': 'решение FOMC',
      'FOMC Press Conference': 'пресс-конференция FOMC',
