      'Core PCE Price Index m/m': 'базовый PCE м/м',
      'PPI m/m': 'ИЦП м/м',
      'Core PPI m/m': 'базовый ИЦП м/м',
      'Non-Farm Employment Change': 'занятость вне с/х (NFP)',
      'ADP Non-Farm Employment Change': 'занятость ADP',
      'Unemployment Rate': 'уровень безработицы',
      'Average Hourly Earnings m/m': 'средняя зарплата м/м',
      'Unemployment Claims': 'заявки на пособие',
      'JOLTS Job Openings': 'вакансии JOLTS',
      'ISM Manufacturing PMI': 'PMI ISM (промышленность)',
      'ISM Services PMI': 'PMI ISM (услуги)',
      'Flash Manufacturing PMI': 'предв. PMI (промышленность)',
      'Flash Services PMI': 'предв. PMI (услуги)',
      'Retail Sales m/m': 'розничные продажи м/м',
      'Core Retail Sales m/m': 'базовые розничные продажи м/м',
      'Advance GDP q/q': 'предв. ВВП кв/кв',
      'Prelim GDP q/q': 'предв. ВВП кв/кв',
      'Final GDP q/q': 'итог. ВВП кв/кв',
      'Fed Chair Powell Speaks': 'выступление Пауэлла',
      'Fed Chair Powell Testifies': 'выступление Пауэлла в Конгрессе',
      'Prelim UoM Consumer Sentiment': 'предв. индекс Мичигана',
      'Consumer Confidence': 'индекс доверия потребителей',
      'Durable Goods Orders m/m': 'заказы на товары длит. пользования м/м',
      'Crude Oil Inventories': 'запасы нефти',
      'Treasury Currency Report': 'валютный отчёт Минфина',
    },
    labels: {
      trend_continuation: 'продолжение тренда',
      session_open_break: 'пробой открытия сессии',
      mean_reversion: 'возврат к средней',
      range_squeeze: 'сжатие диапазона',
      none: 'нет кандидата',
    },
    sessionNames: {
      asia: 'азиатской',
      london: 'лондонской',
      ny_overlap: 'лондон/нью-йорк',
      ny_afternoon: 'нью-йоркской',
      late: 'поздней',
    },
    notes: {
      trendUp: (lvl) => `Тренд 1ч вверх, цена удержала 20 EMA на ${lvl}.`,
      trendDown: (lvl) => `Тренд 1ч вниз, цена отбилась от 20 EMA на ${lvl}.`,
      sessionBreak: (session, up, lvl) =>
        `Пробой ${session} сессии: ${up ? 'максимум' : 'минимум'} первого часа на ${lvl}.`,
      stretch: (atr, above) =>
        `Отклонение ${atr} ATR ${above ? 'выше' : 'ниже'} 20 EMA — риск возврата.`,
      squeeze: (range, ratio, lo, hi) =>
        `Сжатие в диапазоне ${range} (${ratio} ATR) — направление не определено до пробоя ${lo}/${hi}.`,
    },
  },
  en: {
    langName: 'English',
    noSetup: 'No setup pattern present.',
    eventNames: {}, // already English — pass through unchanged
    labels: {
      trend_continuation: 'trend continuation',
      session_open_break: 'session open break',
      mean_reversion: 'mean reversion',
      range_squeeze: 'range squeeze',
      none: 'no candidate',
    },
    sessionNames: {
      asia: 'Asia',
      london: 'London',
      ny_overlap: 'London/NY',
      ny_afternoon: 'New York',
      late: 'late',
    },
    notes: {
      trendUp: (lvl) => `1h trend up, price held the 20 EMA at ${lvl}.`,
      trendDown: (lvl) => `1h trend down, price rejected the 20 EMA at ${lvl}.`,
      sessionBreak: (session, up, lvl) =>
        `Broke the ${session} opening range ${up ? 'high' : 'low'} at ${lvl}.`,
      stretch: (atr, above) =>
        `Stretched ${atr} ATR ${above ? 'above' : 'below'} the 20 EMA — snapback risk.`,
      squeeze: (range, ratio, lo, hi) =>
        `Compressed into a ${range} range (${ratio} ATR) — direction unresolved until ${lo}/${hi} breaks.`,
    },
  },
};

const t = STRINGS[c.lang] || STRINGS.ru;

/** Localise a ForexFactory event title, or return it unchanged if unmapped. */
function eventName(title) {
  if (!title) return title;
  return (t.eventNames && t.eventNames[title]) || title;
}
const eventNextLocal = eventName(gate.nextEventTitle);
const eventLastLocal = eventName(gate.lastEventTitle);

// ------------------------------------------------------------- generators ---
// Order matters only for tie-breaking (earlier wins an exact tie).

const GENERATORS = [
  // REMOVED (Task 1.2): pdh_pdl_break and liquidity_sweep. The offline backtest
  // (workflow/backtest/) measured both with negative expectancy over ~7 weeks —
  // pdh_pdl_break at 46% of all signals and −0.10 avgR was the single biggest
  // drag on the system. Deleting them lifted distinct-prediction avgR from −0.10
  // to +0.05. If a future data source (Phase 2 real yields / DXY) makes a
  // break-based setup viable, re-add it here and re-run the backtest before
  // trusting it — don't restore on intuition.
  {
    id: 'trend_continuation',
    label: t.labels.trend_continuation,
    signalType: 'continuation',
    generate: (x) => {
      if (x.emaStack === 0 || x.ema20 === null) return null;
      const dist = (x.price - x.ema20) / x.atr1h;

      // Long: pulled back toward EMA20 from above and holding.
      if (x.emaStack === 1 && dist >= -0.2 && dist <= 0.8) {
        return {
          direction: 'long',
          base: Math.abs(dist) < 0.3 ? 42 : 35,
          structuralLevel: x.ema20,
          note: t.notes.trendUp(x.ema20),
        };
      }
      // Short: mirror.
      if (x.emaStack === -1 && dist <= 0.2 && dist >= -0.8) {
        return {
          direction: 'short',
          base: Math.abs(dist) < 0.3 ? 42 : 35,
          structuralLevel: x.ema20,
          note: t.notes.trendDown(x.ema20),
        };
      }
      return null;
    },
  },

  {
    id: 'session_open_break',
    label: t.labels.session_open_break,
    signalType: 'breakout',
    generate: (x) => {
      if (x.firstHourHigh === null || x.firstHourLow === null) return null;
      // Meaningless while still inside the first hour of the session.
      if (x.hourUTC <= x.sessionStartHour) return null;
      if (x.session !== 'london' && x.session !== 'ny_overlap') return null;

      const sessionName = t.sessionNames[x.session] || x.session;
      if (x.price > x.firstHourHigh) {
        return {
          direction: 'long',
          base: 40,
          structuralLevel: x.firstHourHigh,
          note: t.notes.sessionBreak(sessionName, true, x.firstHourHigh),
        };
      }
      if (x.price < x.firstHourLow) {
        return {
          direction: 'short',
          base: 40,
          structuralLevel: x.firstHourLow,
          note: t.notes.sessionBreak(sessionName, false, x.firstHourLow),
        };
      }
      return null;
    },
  },

  {
    id: 'mean_reversion',
    label: t.labels.mean_reversion,
    signalType: 'reversion',
    generate: (x) => {
      if (x.ema20 === null) return null;
      const stretch = (x.price - x.ema20) / x.atr1h;
      if (Math.abs(stretch) < 2.0) return null;

      const direction = stretch > 0 ? 'short' : 'long';
      return {
        direction,
        base: Math.abs(stretch) > 2.5 ? 42 : 38,
        structuralLevel: direction === 'short' ? x.last15.high : x.last15.low,
        note: t.notes.stretch(Math.abs(stretch).toFixed(1), stretch > 0),
        stretch: Math.round(stretch * 100) / 100,
      };
    },
  },

  {
    id: 'range_squeeze',
    label: t.labels.range_squeeze,
    signalType: 'compression',
    // Directionless by construction: compression says a move is coming, not
    // which way. Capped at LOW downstream so it can never publish a
    // directional call without an invalidation level.
    generate: (x) => {
      if (x.compressionRatio >= 0.6) return null;
      return {
        direction: 'none',
        base: 35,
        structuralLevel: null,
        note: t.notes.squeeze(x.range8, x.compressionRatio, x.range8Low, x.range8High),
        rangeHigh: x.range8High,
        rangeLow: x.range8Low,
      };
    },
  },
];

// ------------------------------------------------------- stop and target ----

function buildLevels(cand, x) {
  if (cand.direction === 'none' || cand.structuralLevel === null) {
    return { entry: x.price, stop: null, target: null, rr: null, stopPct: null };
  }

  const entry = x.price;
  const isLong = cand.direction === 'long';

  const rawStop = isLong
    ? cand.structuralLevel - STOP_BUFFER_ATR * x.atr1h
    : cand.structuralLevel + STOP_BUFFER_ATR * x.atr1h;

  // Clamp the DISTANCE, not the level, so the published stop always sits
  // inside the 0.30%–0.80% band the spec requires.
  const rawDist = Math.abs(entry - rawStop);
  const dist = Math.min(
    Math.max(rawDist, STOP_FLOOR_PCT * entry),
    STOP_CEIL_PCT * entry,
  );
  const stop = isLong ? entry - dist : entry + dist;

  // Nearest opposing structural level that is far enough to be worth targeting
  // but close enough to still be an INTRADAY target.
  //
  // The upper bound matters more than it looks. Without it, a swing-scale level
  // (a 20-bar 1h swing high can sit 3-4% away) becomes the target of a signal
  // whose stop is 0.5% — producing a published R:R of 7, which is not a real
  // edge, it is a horizon mismatch. Worse, that fake ratio then earns the
  // goodRR bonus and inflates the score. Beyond MAX_TARGET_R we ignore the
  // level and fall back to a plain 2R, which is honest for a 1-12h hold.
  const candidates = isLong
    ? [x.priorDayHigh, x.swingHigh, x.sessionHigh]
    : [x.priorDayLow, x.swingLow, x.sessionLow];

  const viable = candidates
    .filter((lvl) => Number.isFinite(lvl))
    .filter((lvl) => (isLong ? lvl > entry : lvl < entry))
    .filter((lvl) => Math.abs(lvl - entry) >= MIN_TARGET_R * dist)
    .filter((lvl) => Math.abs(lvl - entry) <= MAX_TARGET_R * dist)
    .sort((a, b) => Math.abs(a - entry) - Math.abs(b - entry));

  const target =
    viable.length > 0
      ? viable[0]
      : isLong
        ? entry + DEFAULT_TARGET_R * dist
        : entry - DEFAULT_TARGET_R * dist;

  return {
    entry: Math.round(entry * 100) / 100,
    stop: Math.round(stop * 100) / 100,
    target: Math.round(target * 100) / 100,
    rr: Math.round((Math.abs(target - entry) / dist) * 100) / 100,
    stopPct: Math.round((dist / entry) * 1000) / 10, // e.g. 0.6 meaning 0.6%
  };
}

// --------------------------------------------------------------- scoring ----

const VOL_FIT = {
  breakout: (atrPct) => atrPct >= 0.12,
  continuation: (atrPct) => atrPct >= 0.10,
  reversion: (atrPct) => atrPct >= 0.15,
  reversal: (atrPct) => atrPct >= 0.12,
  compression: (atrPct) => atrPct <= 0.20,
};

const SESSION_FIT = {
  breakout: ['london', 'ny_overlap'],
  continuation: ['london', 'ny_overlap', 'ny_afternoon'],
  reversion: ['asia', 'ny_afternoon', 'late'],
  reversal: ['london', 'ny_overlap', 'ny_afternoon'],
  compression: ['asia', 'late'],
};

function score(cand, gen, x, levels) {
  const components = {};
  let total = cand.base;
  components.base = cand.base;

  const dirSign = cand.direction === 'long' ? 1 : cand.direction === 'short' ? -1 : 0;

  // + 1h EMA stack agrees
  if (dirSign !== 0 && x.emaStack === dirSign) {
    total += WEIGHTS.emaAgrees;
    components.emaAgrees = WEIGHTS.emaAgrees;
  }

  // + dollar direction supports the trade (EUR/USD up => dollar down => gold up)
  if (dirSign !== 0 && x.dollarDir === dirSign) {
    total += WEIGHTS.dollarAgrees;
    components.dollarAgrees = WEIGHTS.dollarAgrees;
  }

  // + volatility regime suits this kind of signal
  const volFn = VOL_FIT[gen.signalType];
  if (volFn && volFn(x.atrPctOfPrice)) {
    total += WEIGHTS.volatilityFits;
    components.volatilityFits = WEIGHTS.volatilityFits;
  }

  // + session suits this kind of signal
  if ((SESSION_FIT[gen.signalType] || []).includes(x.session)) {
    total += WEIGHTS.sessionFits;
    components.sessionFits = WEIGHTS.sessionFits;
  }

  // + reward:risk is worth taking
  if (levels.rr !== null && levels.rr >= 2) {
    total += WEIGHTS.goodRR;
    components.goodRR = WEIGHTS.goodRR;
  }

  // - event risk. Unknown calendar data is treated as the 120-minute case:
  //   assume risk rather than assume safety.
  const m = gate.minutesToNext;
  if (gate.eventDataUnknown) {
    total += WEIGHTS.eventWithin120;
    components.eventDataUnknown = WEIGHTS.eventWithin120;
  } else if (m !== null && m !== undefined) {
    if (m <= 60) {
      total += WEIGHTS.eventWithin60;
      components.eventWithin60 = WEIGHTS.eventWithin60;
    } else if (m <= 120) {
      total += WEIGHTS.eventWithin120;
      components.eventWithin120 = WEIGHTS.eventWithin120;
    }
  }

  // OPTIONAL 10th TERM, deliberately not enabled: a penalty for the ~15 min
  // after a print, when price is still noise. `gate.inPostEventWindow` carries
  // the flag and the message annotates it, but it does not affect the score,
  // because the approved spec defines exactly nine terms. Enable by
  // uncommenting — and log the change, so the Sheets history stays comparable.
  // if (gate.inPostEventWindow) { total -= 15; components.postEvent = -15; }

  // - daily trend disagrees with the trade
  if (dirSign !== 0 && x.dailyTrend !== 0 && x.dailyTrend !== dirSign) {
    total += WEIGHTS.dailyConflict;
    components.dailyConflict = WEIGHTS.dailyConflict;
  }

  // - breakouts during the Asia session are usually noise
  if (gen.signalType === 'breakout' && x.session === 'asia') {
    total += WEIGHTS.breakoutInAsia;
    components.breakoutInAsia = WEIGHTS.breakoutInAsia;
  }

  return {
    score: Math.max(0, Math.min(100, Math.round(total))),
    components,
  };
}

// -------------------------------------------------------------- evaluate ----

// ponytail: backtest-only seam. n8n never sets this env var — and its sandbox
// may not even expose `process` — so the typeof guard makes this an empty set
// live: zero behaviour change. The backtest sets BACKTEST_DISABLE=id,id to
// measure the reshuffled system when a generator is deleted.
const DISABLED = new Set(
  (typeof process !== 'undefined' && process.env && process.env.BACKTEST_DISABLE
    ? process.env.BACKTEST_DISABLE.split(',')
    : []
  )
    .map((s) => s.trim())
    .filter(Boolean),
);

const evaluated = [];

for (let i = 0; i < GENERATORS.length; i++) {
  const gen = GENERATORS[i];
  if (DISABLED.has(gen.id)) continue;
  let cand;
  try {
    cand = gen.generate(c);
  } catch (err) {
    // A broken generator must not take the whole run down with it.
    console.log(`Generator ${gen.id} threw: ${err.message}`);
    continue;
  }
  if (!cand) continue;

  const levels = buildLevels(cand, c);
  const { score: sc, components } = score(cand, gen, c, levels);

  evaluated.push({
    id: gen.id,
    label: gen.label,
    signalType: gen.signalType,
    order: i,
    direction: cand.direction,
    score: sc,
    components,
    note: cand.note,
    structuralLevel: cand.structuralLevel,
    ...levels,
    extras: {
      extension: cand.extension ?? null,
      stretch: cand.stretch ?? null,
      rangeHigh: cand.rangeHigh ?? null,
      rangeLow: cand.rangeLow ?? null,
    },
  });
}

// Highest score wins. Ties -> higher R:R, then earlier generator order.
evaluated.sort((a, b) => {
  if (b.score !== a.score) return b.score - a.score;
  const arr = a.rr === null ? -1 : a.rr;
  const brr = b.rr === null ? -1 : b.rr;
  if (brr !== arr) return brr - arr;
  return a.order - b.order;
});

const winner = evaluated.length > 0 ? evaluated[0] : null;

// ------------------------------------------------------------- banding -----

function bandFor(w) {
  if (!w || w.score < BANDS.low) return 'NO_EDGE';
  if (w.score >= BANDS.high) return 'HIGH';
  if (w.score >= BANDS.medium) return 'MEDIUM';
  return 'LOW';
}

let conviction = bandFor(winner);

// A directionless signal never claims a direction, so it can never publish as
// an actionable HIGH/MEDIUM call. Cap at LOW.
if (winner && winner.direction === 'none' && conviction !== 'NO_EDGE') {
  conviction = 'LOW';
}

// CROWDING CEILING (Task 1.3). A score only reaches ~90 when every confirmation
// stacks — EMA, dollar, session, R:R and the daily trend all agree. The offline
// backtest showed that band is a trap: the 90–99 bucket ran 13% wins / −0.58
// avgR over ~7 weeks, by far the worst of any score band, while 70–89 was the
// best (+0.20). "Everyone agrees" means the move is already priced. So an
// over-confirmed setup is demoted to LOW (silent) rather than shouted as HIGH.
// The cap is recorded in components so the Sheet shows why it was downgraded.
// Regime-dependent — revisit once live outcome data (Task 0.2) accumulates.
if (winner && winner.score >= CROWDED_CEILING && conviction !== 'NO_EDGE') {
  conviction = 'LOW';
  winner.components = { ...winner.components, crowdedCap: winner.score };
}

// ------------------------------------------------------ repeat detection ----

const sd = $getWorkflowStaticData('global');
const signature = winner ? `${winner.id}|${winner.direction}` : 'none|none';

if (sd.lastSignal === signature) {
  sd.consecutiveCount = (sd.consecutiveCount || 1) + 1;
} else {
  sd.consecutiveCount = 1;
  sd.lastSignal = signature;
}
const consecutive = sd.consecutiveCount;

// ---------------------------------------------------------------- output ----

// Runner-up context, for the NO_EDGE message and for post-hoc analysis.
const runnerUp = evaluated.length > 1 ? evaluated[1] : null;

/**
 * Facts handed to the LLM. Built here because this node owns every number in
 * it; the LLM node's own config then stays a one-line expression.
 *
 * This string is ALSO the whitelist the Format node validates the LLM's reply
 * against — any number in the reply that is not in here (and is above 10) gets
 * the reply discarded in favour of the template. So do not trim it below the
 * set of numbers the prose is legitimately allowed to mention.
 */
function buildFacts(w, band) {
  const lines = [
    `asset: ${c.label} (${c.symbol})`,
    `price: ${c.price}`,
    `24h change: ${c.change24hPct}%`,
    `session: ${c.session.replace('_', ' ')}`,
    `1h trend: ${c.emaStack === 1 ? 'up' : c.emaStack === -1 ? 'down' : 'mixed'}`,
    `20 EMA: ${c.ema20}`,
    `dollar: ${c.dollarDir === 1 ? 'softening' : c.dollarDir === -1 ? 'firming' : 'flat'}`,
    `prior day high: ${c.priorDayHigh}`,
    `prior day low: ${c.priorDayLow}`,
    `setup: ${w ? w.label : 'none'}`,
    `direction: ${w ? w.direction : 'none'}`,
    `conviction: ${band} (${w ? w.score : 0} of 100)`,
    `observation: ${w ? w.note : 'No setup pattern present.'}`,
  ];
  if (w && w.entry !== null && w.stop !== null) {
    lines.push(`entry: ${w.entry}`, `stop: ${w.stop}`, `target: ${w.target}`, `risk reward: ${w.rr}`);
  }
  if (gate.minutesToNext !== null && gate.minutesToNext !== undefined) {
    // Localised name so the prose matches the message chrome instead of echoing
    // the raw English title into a Russian sentence.
    lines.push(`next high-impact USD event: ${eventNextLocal} in ${gate.nextEventHuman}`);
  }
  return lines.join('\n');
}
// The facts stay in English regardless of output language: they are machine
// input, the LLM reads them fine, and keeping them stable means the Format
// node's number whitelist is unaffected by a language change.

return [
  {
    json: {
      ...c,
      signal: winner
        ? {
            id: winner.id,
            label: winner.label,
            signalType: winner.signalType,
            direction: winner.direction,
            score: winner.score,
            conviction,
            entry: winner.entry,
            stop: winner.stop,
            target: winner.target,
            rr: winner.rr,
            stopPct: winner.stopPct,
            note: winner.note,
            components: winner.components,
            extras: winner.extras,
          }
        : {
            id: 'none',
            label: t.labels.none,
            signalType: null,
            direction: 'none',
            score: 0,
            conviction: 'NO_EDGE',
            entry: c.price,
            stop: null,
            target: null,
            rr: null,
            stopPct: null,
            note: t.noSetup,
            components: {},
            extras: {},
          },
      llmFacts: buildFacts(winner, conviction),
      // Consumed by the LLM prompt in build.mjs, so the language setting has a
      // single home in 01-fetch-plan.js rather than being duplicated there.
      langName: t.langName,
      // Localised event titles for Format's chrome — same source as the facts,
      // so prose and chrome always agree.
      eventNextLocal,
      eventLastLocal,
      consecutive,
      candidateCount: evaluated.length,
      runnerUp: runnerUp
        ? { id: runnerUp.id, label: runnerUp.label, score: runnerUp.score }
        : null,
      allCandidates: evaluated.map((e) => ({
        id: e.id,
        direction: e.direction,
        score: e.score,
      })),
    },
    pairedItem: { item: 0 },
  },
];

/* ============================================================================
 * NODE 5/5 — Format message
 * n8n Code node · Language: JavaScript · Mode: Run Once for All Items
 * ----------------------------------------------------------------------------
 * Builds the Telegram HTML message and the Google Sheets log row.
 *
 * IMPORTANT n8n BEHAVIOUR: the Basic LLM Chain node REPLACES the item json
 * with {text: "..."} — it does not pass input fields through. So the scorer's
 * data is read by node reference, and only the prose comes from $input.
 *
 * THE LLM'S LEASH. Its reply is untrusted text. Three checks before it reaches
 * a published message:
 *   1. length cap
 *   2. every number it states (above 10) must appear in the facts it was given
 *   3. HTML-escape what survives
 * Any failure -> the deterministic template is used instead. The message always
 * posts; the prose is the only thing that can degrade.
 *
 * WHY parse_mode HTML AND NOT MarkdownV2: MarkdownV2 requires escaping ~18
 * characters and returns 400 on any unescaped '.' or '-'. Both appear in every
 * price we publish.
 * ==========================================================================*/

const MAX_PROSE_CHARS = 200;
const SMALL_NUMBER_CEILING = 10; // ordinals, "1h", "20 EMA" — never a gold level

const s = $('Scorer').first().json;
const sig = s.signal;
const gate = s.eventGate || {};

const llmRaw = ($input.first().json && $input.first().json.text) || '';

/* ---------------------------------------------------------------- strings ---
 * Language comes from LANG in 01-fetch-plan.js — do not set it here.
 * This table owns the message chrome. The Scorer owns setup notes and generator
 * names, and hands them over already localised.
 *
 * Adding a language: add a block here, add one to STRINGS in 04-scorer.js, and
 * set LANG in 01-fetch-plan.js. Nothing else changes.
 */
const STRINGS = {
  ru: {
    dir: { long: 'ЛОНГ', short: 'ШОРТ' },
    conviction: 'уверенность',
    entry: 'Вход',
    stop: 'Стоп',
    target: 'Цель',
    rr: 'R:R',
    market: 'по рынку',
    // Full phrases, not an adjective plus a glued-on noun: "лондон/нью-йорк
    // сессия" is ungrammatical, and Russian adjective agreement varies by
    // session name. Any future language gets the same freedom.
    sessions: {
      asia: 'азиатская сессия',
      london: 'лондонская сессия',
      ny_overlap: 'перекрытие Лондон/Нью-Йорк',
      ny_afternoon: 'нью-йоркская сессия',
      late: 'поздняя сессия',
    },
    h24: '24ч',
    noEdge: 'НЕТ СИГНАЛА',
    standAside: 'вне рынка',
    watching: 'Наблюдаем',
    noCall: 'Направление не определено до пробоя одной из границ.',
    bestCandidate: (label, score) =>
      `Лучший кандидат — ${label}, ${score}/100. Действовать не на чем.`,
    nothingWorth: 'Сетап не сформирован. Действовать не на чем.',
    consecutive: (n) => `↻ ${n}-й запуск подряд — без изменений`,
    calendarDown: '⚠ Календарь событий недоступен — оценка с осторожностью',
    eventImminent: (title, when) => `⚠ ${title} через ${when}`,
    postEvent: (title, min) => `⚠ ${title} вышло ${min} мин назад — цена ещё не устоялась`,
    nextEvent: (when, title) => `Следующее важное событие по USD: через ${when} (${title})`,
    health: (msg) => `состояние: ${msg}`,
    healthCounts: (posted, skipped) =>
      `${posted} отправлено / ${skipped} пропущено с последней проверки`,
    disclaimer: 'Аналитический сигнал · решения принимаете самостоятельно',
    truncated: '…обрезано',
    units: { min: 'мин', h: 'ч', d: 'д' },
  },
  en: {
    dir: { long: 'LONG', short: 'SHORT' },
    conviction: 'conviction',
    entry: 'Entry',
    stop: 'Stop',
    target: 'Target',
    rr: 'R:R',
    market: 'market',
    sessions: {
      asia: 'asia session',
      london: 'london session',
      ny_overlap: 'ny overlap',
      ny_afternoon: 'ny afternoon',
      late: 'late session',
    },
    h24: '24h',
    noEdge: 'NO EDGE',
    standAside: 'stand aside',
    watching: 'Watching',
    noCall: 'No directional call until one side breaks.',
    bestCandidate: (label, score) =>
      `Best candidate was ${label} at ${score}/100. Nothing worth acting on.`,
    nothingWorth: 'No setup pattern present. Nothing worth acting on.',
    consecutive: (n) => {
      const ord = n === 2 ? '2nd' : n === 3 ? '3rd' : `${n}th`;
      return `↻ ${ord} consecutive run — unchanged`;
    },
    calendarDown: '⚠ Event calendar unavailable — scored cautiously',
    eventImminent: (title, when) => `⚠ ${title} in ${when}`,
    postEvent: (title, min) => `⚠ ${title} printed ${min} min ago — price still settling`,
    nextEvent: (when, title) => `Next high-impact USD event: ${when} (${title})`,
    health: (msg) => `health: ${msg}`,
    healthCounts: (posted, skipped) => `${posted} posted / ${skipped} skipped since last check`,
    disclaimer: 'Analytical signal · you make your own decisions',
    truncated: '…truncated',
    units: { min: 'min', h: 'h', d: 'd' },
  },
};

// Event titles are localised by the Scorer (which owns the map, because it also
// builds the LLM facts) and arrive here already translated as eventNextLocal /
// eventLastLocal. Format just displays them.

const t = STRINGS[s.lang] || STRINGS.ru;

// ------------------------------------------------------------- validation ---

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/** Normalised numeric tokens: "2,412.30" -> "2412.30" */
function numberTokens(str) {
  const matches = String(str).replace(/,/g, '').match(/\d+(?:\.\d+)?/g);
  return matches || [];
}

function validateProse(raw, factsStr) {
  const text = String(raw).trim();
  if (!text) return { ok: false, reason: 'empty' };
  if (text.length > MAX_PROSE_CHARS) {
    return { ok: false, reason: `too long (${text.length} chars)` };
  }

  const allowed = new Set(numberTokens(factsStr));
  for (const tok of numberTokens(text)) {
    if (parseFloat(tok) <= SMALL_NUMBER_CEILING) continue; // harmless small ints
    if (!allowed.has(tok)) {
      return { ok: false, reason: `invented number "${tok}"` };
    }
  }
  return { ok: true, text };
}

/** Deterministic fallback — always available, never wrong. */
function templateProse() {
  if (sig.conviction === 'NO_EDGE') {
    return s.runnerUp
      ? t.bestCandidate(s.runnerUp.label, s.runnerUp.score)
      : t.nothingWorth;
  }
  return sig.note; // already localised by the Scorer
}

const verdict = validateProse(llmRaw, s.llmFacts);
const prose = verdict.ok ? escapeHtml(verdict.text) : templateProse();

if (!verdict.ok) {
  console.log(`LLM prose rejected (${verdict.reason}); using template. Raw: ${String(llmRaw).slice(0, 300)}`);
}

// ------------------------------------------------------------- heartbeat ----

const sd = $getWorkflowStaticData('global');
const todayUTC = s.tsUtc.slice(0, 10);

sd.dayPosted = (sd.dayPosted || 0) + 1;

let heartbeat = null;
if (sd.heartbeatDate !== todayUTC && new Date(s.tsUtc).getUTCHours() >= 8) {
  const posted = sd.dayPosted || 0;
  const skipped = sd.skipped || 0;
  heartbeat = t.healthCounts(posted, skipped);
  sd.heartbeatDate = todayUTC;
  sd.dayPosted = 0;
  sd.skipped = 0;
}

// --------------------------------------------------------------- message ----

const arrow = s.change24hPct > 0.05 ? '▲' : s.change24hPct < -0.05 ? '▼' : '▬';
// Explicit +/- with an ASCII hyphen, matching the stop/target block. (An arrow
// already shows direction, but the signed number is unambiguous on its own.)
const chg = `${s.change24hPct > 0 ? '+' : ''}${s.change24hPct}`;
const sessionLabel = t.sessions[s.session] || s.session.replace(/_/g, ' ');
// Session names are our own strings, never user input — but escape anyway so a
// future language containing & or < cannot break the HTML parse.

function fmt(n) {
  return n === null || n === undefined
    ? '—'
    : Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

const lines = [];

// Header
lines.push(`${s.emoji} <b>${escapeHtml(s.label)} · ${escapeHtml(s.symbol)}</b>   ${fmt(s.price)}`);
lines.push(
  `${arrow} ${chg}% (${t.h24}) · ${escapeHtml(sessionLabel)}`,
);
lines.push('');

// Body
if (sig.conviction === 'NO_EDGE') {
  lines.push(`<b>${t.noEdge}</b> · ${t.standAside}`);
  lines.push(prose);
} else if (sig.direction === 'none') {
  // range_squeeze and any future directionless signal: levels, never a call.
  lines.push(`<b>${escapeHtml(sig.label.toUpperCase())}</b> · ${t.conviction} ${sig.score}/100`);
  lines.push(`${t.watching}  ${fmt(sig.extras.rangeLow)} / ${fmt(sig.extras.rangeHigh)}`);
  lines.push(t.noCall);
  lines.push('');
  lines.push(prose);
} else {
  const isLong = sig.direction === 'long';
  const dir = isLong ? t.dir.long : t.dir.short;
  const tgtPct = ((Math.abs(sig.target - sig.entry) / sig.entry) * 100).toFixed(1);

  // Signs are relative to ENTRY, not to the trade's intent. On a short the stop
  // sits ABOVE entry and the target BELOW, so the signs invert. Getting this
  // backwards puts "-0.3%" next to a higher number, which reads as a typo at
  // best and as the wrong direction at worst.
  const stopSign = isLong ? '-' : '+';
  const tgtSign = isLong ? '+' : '-';

  // Pad the labels to a common width so the monospace block stays aligned in
  // any language — "Entry/Stop/Target" and "Вход/Стоп/Цель" differ in length.
  const w = Math.max(t.entry.length, t.stop.length, t.target.length) + 3;
  const pad = (label) => label + ' '.repeat(Math.max(1, w - label.length));

  lines.push(`<b>${dir}</b> · ${t.conviction} ${sig.score}/100`);
  // One <pre> block, not three inline <code> spans. Stacked <code> aligns on
  // Telegram desktop but not mobile, which pads inline code independently.
  // <pre> is the only element Telegram renders true fixed-width on every client.
  const block = [
    `${pad(t.entry)}${fmt(sig.entry)}  (${t.market})`,
    `${pad(t.stop)}${fmt(sig.stop)}  (${stopSign}${sig.stopPct}%)`,
    `${pad(t.target)}${fmt(sig.target)}  (${tgtSign}${tgtPct}%)  ·  ${t.rr} ${sig.rr}`,
  ].join('\n');
  lines.push(`<pre>${block}</pre>`);
  lines.push('');
  lines.push(prose);
}

// Repeat marker — only for a live directional signal. "Still LONG, 3rd run"
// says the setup is holding; "still no edge, 15th run" just climbs forever and
// clutters every quiet window (most 30-min windows are NO_EDGE).
if (s.consecutive > 1 && sig.direction !== 'none') {
  lines.push('');
  lines.push(`<i>${t.consecutive(s.consecutive)}</i>`);
}

// Event line. The countdown from the Event gate is language-neutral digits plus
// a unit suffix, so translate the unit here rather than re-deriving the value.
const when = gate.nextEventHuman
  ? gate.nextEventHuman
      .replace(/\bmin\b/, t.units.min)
      .replace(/(\d)h$/, `$1${t.units.h}`)
      .replace(/(\d)d$/, `$1${t.units.d}`)
  : null;

lines.push('');
const nextEventTitleLocal = s.eventNextLocal || gate.nextEventTitle;
const lastEventTitleLocal = s.eventLastLocal || gate.lastEventTitle;

if (gate.eventDataUnknown) {
  lines.push(`<i>${t.calendarDown}</i>`);
} else if (gate.minutesToNext !== null && gate.minutesToNext <= 60) {
  lines.push(`<b>${t.eventImminent(escapeHtml(nextEventTitleLocal), when)}</b>`);
} else if (gate.inPostEventWindow) {
  lines.push(`<i>${t.postEvent(escapeHtml(lastEventTitleLocal), gate.minutesSinceLast)}</i>`);
} else if (when) {
  lines.push(`<i>${t.nextEvent(when, escapeHtml(nextEventTitleLocal))}</i>`);
}

// Footer
if (heartbeat) lines.push(`<i>${t.health(heartbeat)}</i>`);
lines.push(`<i>${t.disclaimer}</i>`);

const messageHtml = lines.join('\n');

// Telegram hard-fails above 4096 characters. We run ~450, but never gamble.
const messageFinal =
  messageHtml.length > 4000 ? `${messageHtml.slice(0, 3950)}\n<i>${t.truncated}</i>` : messageHtml;

// Notify only on HIGH and MEDIUM. This is what keeps 48 messages/day tolerable:
// the channel carries everything, the phone only buzzes for something actionable.
const notified = sig.conviction === 'HIGH' || sig.conviction === 'MEDIUM';

// ---------------------------------------------------------------- output ----

return [
  {
    json: {
      // --- Telegram ---
      messageHtml: messageFinal,
      disableNotification: !notified,

      // --- Google Sheets log (column names must match the sheet header) ---
      ts_utc: s.tsUtc,
      price: s.price,
      signal_id: sig.id,
      direction: sig.direction,
      score: sig.score,
      conviction: sig.conviction,
      entry: sig.entry,
      stop: sig.stop,
      target: sig.target,
      rr: sig.rr,
      components: JSON.stringify(sig.components),
      event_gate_min: gate.minutesToNext === null || gate.minutesToNext === undefined ? '' : gate.minutesToNext,
      session: s.session,
      consecutive: s.consecutive,
      notified: notified,
      outcome_24h: '', // filled manually in phase 1; phase-2 workflow backfills

      // --- diagnostics, not logged to the sheet ---
      _proseSource: verdict.ok ? 'llm' : `template (${verdict.reason})`,
      _candidateCount: s.candidateCount,
      _allCandidates: s.allCandidates,
      _calendarSource: gate.calendarSource,
    },
    pairedItem: { item: 0 },
  },
];

